
window.FV77_SUBMENU_ASSETS={"select_select": "data:image/png;base64,", "select_move": "data:image/png;base64,", "select_recycle": "data:image/png;base64,", "plow_plow": "data:image/png;base64,", "plow_seeder": "data:image/png;base64,", "plow_harvester": "data:image/png;base64,", "plow_tractor": "data:image/png;base64,"};
(function(){"use strict";
const menu=document.getElementById('fv38Submenu');
const selectArrow=document.getElementById('fv38MultiArrow');
const plowArrow=document.getElementById('fv38PlowArrow');
if(!menu)return;
function sync(){
 const isSelect=selectArrow&&selectArrow.getAttribute('aria-expanded')==='true';
 const isPlow=plowArrow&&plowArrow.getAttribute('aria-expanded')==='true';
 if(menu.hidden||(!isSelect&&!isPlow)){menu.removeAttribute('data-v77');return;}
 const type=isSelect?'select':'plow';menu.setAttribute('data-v77',type);
 const keyMap=type==='select'?['select','move','recycle']:['plow','seeder','harvester','tractor'];
 const options=Array.from(menu.querySelectorAll('button'));
 options.forEach((btn,i)=>{
   const plain=(btn.textContent||'').toLowerCase();
   let match=keyMap.find(x=>plain.includes(x));
   if(!match) match=keyMap[i];
   if(match&&window.FV77_SUBMENU_ASSETS[type+'_'+match]){
      btn.style.setProperty('--fv77-submenu-icon','url("'+window.FV77_SUBMENU_ASSETS[type+'_'+match]+'")');
      btn.setAttribute('data-v77-icon',match);
   }
 });
}
let queued=false;function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;sync();})}
new MutationObserver(schedule).observe(menu,{childList:true,subtree:false,attributes:true,attributeFilter:['hidden']});
if(selectArrow)new MutationObserver(schedule).observe(selectArrow,{attributes:true,attributeFilter:['aria-expanded']});
if(plowArrow)new MutationObserver(schedule).observe(plowArrow,{attributes:true,attributeFilter:['aria-expanded']});
sync();
})();
